  { id: "basics",     color: "var(--c-yellow)", ink: "var(--navy)", en: "Project Basics",       de: "Projektgrundlagen" },
  { id: "people",     color: "var(--c-blue)",   ink: "#fff",        en: "People & Data",        de: "Menschen & Daten" },
  { id: "context",    color: "var(--c-sky)",    ink: "var(--navy)", en: "Context",              de: "Kontext" },
  { id: "interact",   color: "var(--c-green)",  ink: "var(--navy)", en: "Auth. Interactions",   de: "Auth.-Interaktionen" },
  { id: "tech",       color: "var(--c-navy)",   ink: "#fff",        en: "Techn. Factors",       de: "Techn. Faktoren" },
  { id: "iterative",  color: "var(--c-orange)", ink: "var(--navy)", en: "Iterative Concepts",   de: "Iterative Konzepte" },
  { id: "reflection", color: "var(--paper)",    ink: "var(--navy)", en: "Reflection",           de: "Reflexion", outline: true }
