window.ADA_METHODS = {
  obs: { en: "Action Observation", de: "Handlungsbeobachtung",
    den: "Go into a context that interests you for the project and collect information on people, environment and interactions. Observe people doing things, ask them about their actions and analyse what that means for the project. Bring prototypes into the context, let people use them, observe what does not work, iterate and come back.",
    dde: "Geht in einen für das Projekt interessanten Kontext und sammelt Informationen über Menschen, Umgebung und Interaktionen. Beobachtet Menschen bei ihren Tätigkeiten, fragt nach ihren Handlungen und analysiert, was das für das Projekt bedeutet. Bringt Prototypen in den Kontext, lasst sie nutzen, beobachtet, was nicht funktioniert, iteriert und kommt wieder." },
  relabel: { en: "Authentication Interaction Relabelling", de: "Authentication Interaction Relabelling",
    den: "Special mechanisms of everyday objects can inspire authentication interactions. Offer interesting objects with several ways to interact, for example a coffee grinder or scissors, and let people try them. Ask specific questions that they answer by interacting with the objects.",
    dde: "Besondere Mechanismen von Alltagsgegenständen können Authentifizierungs-Interaktionen inspirieren. Bietet interessante Objekte mit mehreren Interaktionsmöglichkeiten an, etwa eine Kaffeemühle oder eine Schere, und lasst Menschen sie ausprobieren. Stellt konkrete Fragen, die sie durch die Interaktion mit den Objekten beantworten." },
  proto: { en: "Authentication Prototyping", de: "Authentication Prototyping",
    den: "Use any material to visualise ideas as prototypes, together with team members, potential users or experts of the context. Iterate from low-fidelity prototypes to high-fidelity ones ready for the market. Focus on functionality and on meeting the user requirements.",
    dde: "Visualisiert Ideen mit beliebigem Material als Prototypen, gemeinsam mit Teammitgliedern, potenziellen Nutzer*innen oder Expert*innen des Kontexts. Iteriert von Low-Fidelity- zu marktreifen High-Fidelity-Prototypen. Konzentriert euch auf die Funktion und die Erfüllung der Nutzeranforderungen." },
  body: { en: "Bodystorming", de: "Bodystorming",
    den: "Act out situations from the targeted context using your own and the users' bodies. Move around with prototypes and reflect in the moment.",
    dde: "Spielt Situationen aus dem Zielkontext mit dem eigenen Körper und dem der Nutzer*innen nach. Bewegt euch mit Prototypen und reflektiert im Moment." },
  routine: { en: "Daily Routine", de: "Tagesablauf",
    den: "Let people visualise their daily routines along a timeline and show what you need for your project. Ask for unusual occurrences and irregularities. Let them reflect on how to improve their routines regarding valuable data and artefacts.",
    dde: "Lasst Menschen ihren Tagesablauf entlang einer Zeitachse visualisieren und darstellen, was ihr für das Projekt braucht. Fragt nach ungewöhnlichen Ereignissen und Unregelmäßigkeiten. Lasst sie reflektieren, wie sie ihren Umgang mit wertvollen Daten und Artefakten verbessern würden." },
  desk: { en: "Desk Research", de: "Desk Research",
    den: "At any stage, research related topics and collect connected projects and scientific texts. Follow the newest trends and innovations in authentication technology. Keep everything relevant in an accessible storage.",
    dde: "Recherchiert in jeder Phase verwandte Themen und sammelt Projekte und wissenschaftliche Texte. Verfolgt Trends und Innovationen in der Authentifizierungstechnik. Legt alles Relevante an einem zugänglichen Ort ab." },
  diary: { en: "Diary", de: "Tagebuch",
    den: "Let people fill out tabular diaries with specific authentication directions or leading questions that help you make decisions in the project.",
    dde: "Lasst Menschen tabellarische Tagebücher mit konkreten Authentifizierungs-Themen oder Leitfragen ausfüllen, die euch bei Projektentscheidungen helfen." },
  workshop: { en: "Interdisciplinary Ideation Workshop", de: "Interdisciplinary Ideation Workshop",
    den: "Bring together team members and people with relevant expertise and experience to answer the project's research questions. Prepare materials that help people express their thoughts and offer co-design methods for the group.",
    dde: "Bringt Teammitglieder und Menschen mit relevanter Expertise und Erfahrung zusammen, um die Forschungsfragen des Projekts zu beantworten. Bereitet Material vor, mit dem sich Gedanken ausdrücken lassen, und bietet Co-Design-Methoden für die Gruppe an." },
  transcripts: { en: "Interaction Transcripts", de: "Interaktionstranskripte",
    den: "Capture what people do and how they interact with relevant objects, prototypes or systems. Then transcribe what people say during action-packed user methods to find out their requirements.",
    dde: "Haltet fest, was Menschen tun und wie sie mit Objekten, Prototypen oder Systemen interagieren. Transkribiert dann, was sie während handlungsintensiver Methoden sagen, um ihre Anforderungen herauszufinden." },
  interview: { en: "Interview", de: "Interview",
    den: "Ask people about topics that interest you for the project. Treat them as experts in their fields and learn from them. Bring supportive material that visualises aspects or processes as a discussion starter.",
    dde: "Befragt Menschen zu Themen, die für das Projekt wichtig sind. Versteht sie als Expert*innen ihres Feldes und lernt von ihnen. Bringt Material mit, das Aspekte oder Prozesse sichtbar macht und das Gespräch anregt." },
  mapping: { en: "Mapping", de: "Mapping",
    den: "Collect topics, user requirements or concepts and relate them visually in a map to get an overview. Use different kinds of lines to differentiate relations. This helps to categorise, visualise complexity and find patterns.",
    dde: "Sammelt Themen, Nutzeranforderungen oder Konzepte und setzt sie in einer Map visuell in Beziehung. Unterscheidet Beziehungen durch verschiedene Linienarten. So lässt sich kategorisieren, Komplexität sichtbar machen und Muster finden." },
  tangibles: { en: "Metaphoric Tangibles", de: "Metaphorische Tangibles",
    den: "Use haptic objects and tinkering material to visualise people's thoughts and let them express complex personal experiences. Choose metaphors for abstract topics and let people play with the materials.",
    dde: "Nutzt haptische Objekte und Bastelmaterial, um Gedanken sichtbar zu machen und komplexe persönliche Erfahrungen ausdrückbar zu machen. Wählt Metaphern für abstrakte Themen und lasst Menschen mit dem Material spielen." },
  process: { en: "Process Analysis", de: "Prozessanalyse",
    den: "Observe relevant processes and visualise them step by step. Analyse which elements matter to people, give them a title and describe them. This can build on observations, interviews, spatial localisation, bodystorming, video analysis, user testing and user journeys.",
    dde: "Beobachtet relevante Prozesse und visualisiert sie Schritt für Schritt. Analysiert, welche Elemente für die Menschen wichtig sind, benennt und beschreibt sie. Grundlage können Beobachtungen, Interviews, Spatial Localisation, Bodystorming, Videoanalyse, User Tests und User Journeys sein." },
  floor: { en: "Security Floor Plans", de: "Sicherheits-Grundrisse",
    den: "On paper or with objects, people visualise floor plans of everyday contexts that secure certain areas. They mark objects, situations, people, paths and movements that lead towards authentication interactions.",
    dde: "Auf Papier oder mit Objekten visualisieren Menschen Grundrisse alltäglicher Orte, die Bereiche absichern. Sie markieren Objekte, Situationen, Personen, Wege und Bewegungen, die zu Authentifizierungs-Interaktionen führen." },
  probes: { en: "Security Probes", de: "Security Probes",
    den: "By collecting probes in contexts where valuables are secured, people share their personal needs and the characteristics of a context. Prepare a set or template that guides them through the collection.",
    dde: "Indem Menschen Probes in Kontexten sammeln, in denen Wertvolles gesichert wird, zeigen sie ihre Bedürfnisse und die Eigenheiten des Kontexts. Bereitet ein Set oder eine Vorlage vor, die durch die Sammlung führt." },
  shadow: { en: "Shadowing", de: "Shadowing",
    den: "Follow people like a shadow through their daily routines, collect observations and visualise processes. Combined with thinking aloud, where people explain what they are doing, you capture how they reflect on their own actions.",
    dde: "Begleitet Menschen wie ein Schatten durch ihren Alltag, sammelt Beobachtungen und visualisiert Abläufe. Kombiniert mit lautem Denken, bei dem sie ihr Tun erklären, erfahrt ihr, wie sie über ihr Handeln reflektieren." },
  spatial: { en: "Spatial Localisation", de: "Spatial Localisation",
    den: "Locate objects, people and scenarios in spaces to find out the requirements of environments. Prepare with floor maps, drawings, photos and videos, then go to the locations, mark interesting elements and move around to experience the space.",
    dde: "Verortet Objekte, Menschen und Szenarien im Raum, um Anforderungen an Umgebungen herauszufinden. Bereitet euch mit Plänen, Zeichnungen, Fotos und Videos vor, geht dann vor Ort, markiert interessante Elemente und erlebt den Raum in Bewegung." },
  storyboard: { en: "Storyboard", de: "Storyboard",
    den: "Let people draw and describe scenarios in a comic-like style. This shows processes step by step and makes the complexity of interactions visible, including the whole user journey with its objects, people and contexts.",
    dde: "Lasst Menschen Szenarien im Comic-Stil zeichnen und beschreiben. So werden Prozesse Schritt für Schritt und die Komplexität von Interaktionen sichtbar, inklusive der ganzen User Journey mit Objekten, Menschen und Kontexten." },
  story: { en: "Storytelling", de: "Storytelling",
    den: "Imagined stories support ideation in a narrative way. People describe contexts, user journeys, objects, dreams and wishes to express their own requirements.",
    dde: "Erdachte Geschichten unterstützen die Ideenfindung erzählerisch. Menschen beschreiben Kontexte, User Journeys, Objekte, Träume und Wünsche und drücken so ihre Anforderungen aus." },
  journey: { en: "User Journey", de: "User Journey",
    den: "Formulate possible scenarios and use cases to conceptualise around them. A user journey shows who does what and why along a timeline, summarises complex processes and shows additional relevant information.",
    dde: "Formuliert mögliche Szenarien und Use Cases, um daran Konzepte zu entwickeln. Eine User Journey zeigt entlang einer Zeitachse, wer was warum tut, fasst komplexe Prozesse zusammen und zeigt weitere relevante Informationen." },
  testing: { en: "User Testing", de: "User Testing",
    den: "Test situations with potential user groups show their requirements towards systems or prototypes directly. Invite people regularly and several times so you iterate in the way they expect.",
    dde: "Testsituationen mit potenziellen Nutzergruppen zeigen direkt ihre Anforderungen an Systeme oder Prototypen. Ladet Menschen regelmäßig und mehrfach ein, damit ihr in ihrem Sinne iteriert." },
  inventory: { en: "Valuable Inventory", de: "Valuable Inventory",
    den: "Ask people to show the valuable objects they use, carry around and own, and let them tell stories of trust and emotional value around them. How specific groups use objects in specific contexts inspires project decisions.",
    dde: "Bittet Menschen, wertvolle Dinge zu zeigen, die sie nutzen, bei sich tragen und besitzen, und lasst sie Geschichten über Vertrauen und emotionalen Wert erzählen. Wie bestimmte Gruppen Dinge in bestimmten Kontexten nutzen, inspiriert Projektentscheidungen." },
  video: { en: "Video Analysis", de: "Videoanalyse",
    den: "Video captures interactions and what people say around certain actions. Choose an analysis technique depending on what the project needs.",
    dde: "Video hält Interaktionen fest und was Menschen bei bestimmten Handlungen sagen. Wählt die Analysetechnik danach, was das Projekt braucht." },
  wizard: { en: "Wizard of Oz", de: "Wizard of Oz",
    den: "Simulate prototype functions to test elements such as authentication technologies without implementing components, algorithms, AI or code. Fake functionality with tinkering material and human interaction.",
    dde: "Simuliert Funktionen eines Prototyps, um Elemente wie Authentifizierungstechniken zu testen, ohne Komponenten, Algorithmen, KI oder Code umzusetzen. Täuscht Funktionen mit Bastelmaterial und menschlichem Zutun vor." },
  all: { en: "All user activities", de: "Alle Nutzer-Aktivitäten", den: "", dde: "" }
};

